import json, re
d = json.load(open('deliverable/estrategia.json'))
schema = {
 "prazo_habilitacao_divergencia": str, "contagem": str,
 "credito_fiduciario": {"valor": int, "sujeito_ao_plano": bool, "retomada_dos_bens_agora": bool, "fundamento": str},
 "credito_quirografario": {"valor": int, "classe": str, "fundamento": str},
 "divergencia_de_valor": {"listado": int, "correto": int},
 "fianca_do_socio": {"extinta_pela_homologacao": bool, "fundamento": str},
 "voto": {"classe": str, "criterio": str},
 "objecao_ao_plano_prazo": str, "acoes_imediatas": list,
}
errs = []
for k, v in schema.items():
    if k not in d: errs.append(f'faltando {k}'); continue
    if isinstance(v, dict):
        for k2, t in v.items():
            if k2 not in d[k]: errs.append(f'faltando {k}.{k2}')
            elif not isinstance(d[k][k2], t): errs.append(f'tipo {k}.{k2}={type(d[k][k2]).__name__}')
    elif not isinstance(d[k], v): errs.append(f'tipo {k}')
print('prazo:', d['prazo_habilitacao_divergencia'], '| formato OK:', bool(re.fullmatch(r'\d{4}-\d{2}-\d{2}', d['prazo_habilitacao_divergencia'])))
print('contagem:', d['contagem'], '| classe:', d['credito_quirografario']['classe'], '| acoes:', len(d['acoes_imediatas']))
print('ERROS:', errs or 'nenhum — schema do contrato 100% atendido')
EOF

